__NUXT_JSONP__("/th/how-to-apply/student-visa-f1/transfer-students", (function(a){return {data:[{details:{slug:"th",pageTitle:"นักเรียนที่ต้องการโอนย้าย | Mentor Language Institute",pageDescription:a,title:"นักเรียนที่ต้องการโอนย้าย",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Ftransfer-students.jpg",subtitle:[a],category:[{title:"ขั้นตอนการสมัคร",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapplication-steps-th.png",listType:"decimal",lists:["สมัครกับ MLI (กรอกใบสมัครออนไลน์)","ส่งเอกสาร","เข้าร่วมการปฐมนิเทศ","รับ I-20"],description:["นักเรียนควรสมัครเรียนกับ MLI 1 หรือ 2 เดือนก่อนวันเริ่มต้น. หลังจากส่งใบสมัครออนไลน์คุณควรสอบถามเจ้าหน้าที่ที่ MLI เพื่อยืนยันขั้นตอนการโอนเงิน เนื่องจากอาจซับซ้อนขึ้นอยู่กับสถานการณ์ของคุณ."],hasApplyNow:true},{title:"นโยบายการยกเลิก",description:["ค่าธรรมเนียมการลงทะเบียน $150 จะถูกเรียกเก็บตอนสมัคร. ค่าธรรมเนียมการลงทะเบียนไม่สามารถคืนเงินได้ หากไม่ได้รับการอนุมัติวีซ่าหรือการลงทะเบียนถูกยกเลิก. "]},{title:"หลังจากส่งใบสมัคร",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapplication-form-en.jpg",description:["หลังจากนักเรียนส่งใบสมัครออนไลน์ MLI จะดำเนินการและส่งลิงก์สำหรับ iMLI (หน้าสมัครออนไลน์ของนักเรียนแต่ละคน). \u003Cbr \u002F\u003Eนักเรียนสามารถทำตามขั้นตอนการสมัครที่ระบุไว้ใน iMLI."]}],applyOnline:{title:"สมัครออนไลน์",description:["กรอกข้อมูลในใบสมัครออนไลน์.\u003Cbr \u002F\u003Eติดต่อเราทาง e-mail หากมีคำถามใด ๆ"],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapply-now-th.png",link:"\u002Fth\u002Fadmission"}},dir:"\u002Ftransfer-students",path:"\u002Ftransfer-students\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:31.294Z",updatedAt:"2025-05-26T12:06:27.949Z"}}],fetch:{},mutations:void 0}}("นักเรียนที่ปัจจุบันเรียนอยู่ที่โรงเรียนอื่นและต้องการเปลี่ยนโรงเรียน.")));